// F-003 - Lead validation + webhook security (R-04).
// Two layers: (1) shared-secret header, (2) HMAC-SHA256 signature over
// `${timestamp}.${JSON.stringify(payload)}` with a 5-minute replay window.
// The signature is verified with Web Crypto - the same algorithm runs on
// the Next.js side (lib/webhook-signing.ts), see docs/ROADMAP.md hardening.
const item = $input.first().json;
const headers = Object.fromEntries(
  Object.entries(item.headers || {}).map(([k, v]) => [String(k).toLowerCase(), v])
);
const body = item.body || {};

if (headers['x-webhook-secret'] !== $env.N8N_WEBHOOK_SECRET) {
  return [{ json: { valid: false, status: 401, error: 'invalid webhook secret' } }];
}

// --- R-04: HMAC signature + replay window ---
const secret = $env.N8N_WEBHOOK_SECRET;
const ts = body.timestamp;
const sig = body.signature;
const payload = body.payload || {};
if (typeof ts !== 'number' || typeof sig !== 'string' || !sig) {
  return [{ json: { valid: false, status: 401, error: 'missing webhook signature' } }];
}
if (Math.abs(Date.now() - ts) > 5 * 60 * 1000) {
  return [{ json: { valid: false, status: 401, error: 'stale webhook timestamp (possible replay)' } }];
}
const crypto = require('node:crypto');
const expected = crypto.createHmac('sha256', secret).update(ts + '.' + JSON.stringify(payload)).digest('hex');
let diff = sig.length !== expected.length ? 1 : 0;
for (let i = 0; i < expected.length; i++) diff |= sig.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) {
  return [{ json: { valid: false, status: 401, error: 'invalid webhook signature' } }];
}

// --- field validation (unchanged) ---
const name = String(payload.name || '').trim();
const email = String(payload.email || '').trim();
const errors = [];
if (!name) errors.push('name is required');
if (!email) errors.push('email is required');
else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('email format is invalid');
if (payload.phone) {
  const digits = String(payload.phone).replace(/\D/g, '');
  if (digits.length < 7 || digits.length > 15) errors.push('phone format is invalid');
}
if (errors.length) {
  return [{ json: { valid: false, status: 422, error: errors.join('; ') } }];
}

return [{ json: {
  valid: true,
  payload: {
    name,
    email,
    phone: payload.phone || null,
    source: payload.source || 'test',
    course_interest: payload.course_interest || null,
    budget: payload.budget || null,
    timeline: payload.timeline || null,
    message: payload.message || null
  }
} }];

// Prepare the OpenAI request (F-004) and carry run_id + payload through the pipeline
const payload = $('Validate & authorize').first().json.payload;
const raw = $('Log run started').first().json;
const body = typeof raw.data === 'string' ? JSON.parse(raw.data) : raw;
const run = Array.isArray(body) ? body[0] : body;

const system = [
  'You are the lead-qualification analyst for a mid-sized education and training company.',
  'You qualify incoming student leads for admissions counselors.',
  'Respond with ONLY a single JSON object with exactly these keys:',
  '{ "score": <integer 0-100, likelihood of conversion>, "category": "HOT"|"WARM"|"COLD", "intent": "HIGH"|"MEDIUM"|"LOW", "course": <string or null>, "timeline": <string or null>, "summary": <one-sentence summary of the lead>, "recommended_action": <concrete next action for the counselor> }'
].join('\n');

const user = [
  'New lead received from ' + (payload.source || 'unknown source') + ':',
  '- name: ' + payload.name,
  '- email: ' + payload.email,
  '- phone: ' + (payload.phone || 'not provided'),
  '- course of interest: ' + (payload.course_interest || 'not specified'),
  '- budget: ' + (payload.budget || 'not specified'),
  '- timeline: ' + (payload.timeline || 'not specified'),
  '- message: ' + (payload.message || '(empty)')
].join('\n');

return [{ json: { run_id: run.id, payload, system, user, _retryCount: $input.first().json._retryCount || 0 } }];

// Schema validation — detects truncation (incomplete JSON) separately
// from malformed JSON so the pipeline can retry the former.
const ai = $('AI lead analysis').first().json;
const prep = $('Prepare AI prompt').first().json;
const retryCount = prep._retryCount || 0;

const text = (ai.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
const truncated = !text.trim().endsWith('}') && !text.trim().endsWith(']');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { ok: false, truncated, _retryCount: retryCount, run_id: prep.run_id, payload: prep.payload, error: 'AI response was not valid JSON' + (truncated ? ' (truncated)' : '') + ': ' + e.message } }];
}

const errors = [];
if (!Number.isInteger(parsed.score) || parsed.score < 0 || parsed.score > 100) errors.push('score must be an integer between 0 and 100');
if (!['HIGH', 'MEDIUM', 'LOW'].includes(parsed.intent)) errors.push('intent must be HIGH, MEDIUM or LOW');
if (typeof parsed.summary !== 'string' || !parsed.summary.trim()) errors.push('summary is required');
if (typeof parsed.recommended_action !== 'string' || !parsed.recommended_action.trim()) errors.push('recommended_action is required');
if (errors.length) {
  return [{ json: { ok: false, truncated: false, _retryCount: retryCount, run_id: prep.run_id, payload: prep.payload, raw: parsed, error: errors.join('; ') } }];
}

return [{ json: { ok: true, truncated: false, _retryCount: retryCount, run_id: prep.run_id, payload: prep.payload, analysis: parsed } }];

// F-005 / F-006 — deterministic scoring + classification thresholds.
// The model proposes a score; the thresholds below are the auditable rule
// that decides HOT/WARM/COLD and intent level.
const { run_id, payload, analysis, _retryCount } = $input.first().json;
const score = analysis.score;
const category = score >= 70 ? 'HOT' : score >= 40 ? 'WARM' : 'COLD';
const intent = score >= 70 ? 'HIGH' : score >= 40 ? 'MEDIUM' : 'LOW';
return [{ json: { run_id, payload, analysis: { ...analysis, score, category, intent }, _retryCount: _retryCount || 0 } }];

// Increment retry counter and feed the original payload back to the AI call.
const item = $input.first().json;
return [{ json: { ...item, _retryCount: (item._retryCount || 0) + 1 } }];

// F-008 - Build the email-draft prompt from the persisted lead + analysis.
const rawAnalysis = $('CRM: insert analysis').first().json;
const body = typeof rawAnalysis.data === 'string' ? JSON.parse(rawAnalysis.data) : rawAnalysis;
const analysis = Array.isArray(body) ? body[0] : body;
const rawLead = $('CRM: insert lead').first().json;
const lead = typeof rawLead.data === 'string' ? JSON.parse(rawLead.data) : rawLead;
const run = $('Score & classify').first().json;
const payload = run.payload;
const a = run.analysis;

const prompt = `You are an admissions counselor at a language school. Write a short, friendly first-touch email to a prospective student.

Student name: ${payload.name}
Course interest: ${payload.course_interest || 'not specified'}
Budget: ${payload.budget || 'not specified'}
Timeline: ${payload.timeline || 'not specified'}
Message from student: ${payload.message || 'none'}

Lead analysis:
- Score: ${a.score}/100
- Category: ${a.category}
- Intent: ${a.intent}
- Summary: ${a.summary}
- Recommended action: ${a.recommended_action}

Return STRICT JSON (no markdown, no commentary) with exactly these keys:
{
  "subject": "email subject line (max 60 chars)",
  "body": "email body (2-4 short paragraphs, personalized)"
}`;

return [{ json: { ...analysis, lead_id: lead.id, prompt } }];

// F-008 — Validate the email draft JSON.
const ai = $('Draft email (AI)').first().json;
const prep = $('Prepare email prompt').first().json;

const text = (ai.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('');
const trimmed = text.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
const truncated = !trimmed.endsWith('}') && !trimmed.endsWith(']');

let parsed;
try {
  parsed = JSON.parse(trimmed);
} catch (e) {
  return [{ json: { ok: false, truncated, lead_id: prep.lead_id, error: 'Email draft was not valid JSON' + (truncated ? ' (truncated)' : '') + ': ' + e.message, email: null, dry_run: true } }];
}

if (typeof parsed.subject !== 'string' || !parsed.subject.trim()) {
  return [{ json: { ok: false, truncated: false, lead_id: prep.lead_id, error: 'email subject is required', email: null, dry_run: true } }];
}
if (typeof parsed.body !== 'string' || !parsed.body.trim()) {
  return [{ json: { ok: false, truncated: false, lead_id: prep.lead_id, error: 'email body is required', email: null, dry_run: true } }];
}

return [{ json: { ok: true, truncated: false, lead_id: prep.lead_id, email: { subject: parsed.subject.trim(), body: parsed.body.trim() }, dry_run: true } }];

// F-010 - Pick an admissions counselor using deterministic round-robin/default logic.
const input = $input.first().json;
const counselors = Array.isArray(input) ? input : $input.all().map(item => item.json);
const rawLead = $('CRM: insert lead').first().json;
const lead = typeof rawLead.data === 'string' ? JSON.parse(rawLead.data) : rawLead;
const run = $('Score & classify').first().json;
const leadId = lead.id;
const sorted = counselors
  .filter(c => c?.id)
  .sort((a, b) => String(a.email || a.id).localeCompare(String(b.email || b.id)));
if (!sorted.length) {
  throw new Error('No admissions counselors available for F-010 assignment');
}
const hash = String(leadId || '').split('').reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
const pick = sorted[hash % sorted.length];
return [{ json: { lead_id: leadId, run_id: run.run_id, assigned_counselor: pick, assignment_note: 'assigned to ' + (pick.full_name || pick.email || pick.id) } }];

// Build all step rows in plain JS (avoids giant JSON template expressions).
// PostgREST bulk insert requires every row to have an IDENTICAL key set -
// absent fields must be explicit nulls (else: "All object keys must match").
const run = $('Score & classify').first().json;
const email = $('Email schema check').first().json;
const assignment = $('Assign counselor').first().json;
const lead = $('CRM: insert lead').first().json;
const leadId = lead.id || JSON.parse(lead.data).id;
const runId = run.run_id;
const now = Date.now();
const a = run.analysis;
const model = ($('AI lead analysis').first().json.modelVersion || 'unknown').replace('models/', '');
const dryRun = $env.GMAIL_DRY_RUN !== 'false';

const rows = [
  { run_id: runId, feature_id: 'F-003', step_name: 'Lead validation', status: 'success', attempt_count: 1, payload_snapshot: { required_fields: true, email_format: 'valid' }, error_detail: null, started_at: new Date(now - 15000).toISOString(), finished_at: new Date(now - 14000).toISOString() },
  { run_id: runId, feature_id: 'F-004', step_name: 'AI lead analysis', status: 'success', attempt_count: run._retryCount || 1, payload_snapshot: { score: a.score, model }, error_detail: null, started_at: new Date(now - 14000).toISOString(), finished_at: new Date(now - 8000).toISOString() },
  { run_id: runId, feature_id: 'F-005/F-006', step_name: 'Scoring & classification', status: 'success', attempt_count: 1, payload_snapshot: { category: a.category, intent: a.intent }, error_detail: null, started_at: new Date(now - 8000).toISOString(), finished_at: new Date(now - 7000).toISOString() },
  { run_id: runId, feature_id: 'F-007', step_name: 'CRM storage', status: 'success', attempt_count: 1, payload_snapshot: { lead_id: leadId }, error_detail: null, started_at: new Date(now - 7000).toISOString(), finished_at: new Date(now - 6000).toISOString() },
  { run_id: runId, feature_id: 'F-008', step_name: 'AI email draft', status: email.ok ? 'success' : 'failed', attempt_count: 1, payload_snapshot: email.ok ? { subject: email.email?.subject } : null, error_detail: email.ok ? null : email.error, started_at: new Date(now - 6000).toISOString(), finished_at: new Date(now - 4000).toISOString() },
  { run_id: runId, feature_id: 'F-009', step_name: 'Email delivery', status: email.ok ? 'success' : 'skipped', attempt_count: 1, payload_snapshot: email.ok ? { delivery: dryRun ? 'dry_run' : 'sent' } : null, error_detail: email.ok ? null : 'skipped (email draft failed)', started_at: new Date(now - 4000).toISOString(), finished_at: new Date(now - 3000).toISOString() },
  { run_id: runId, feature_id: 'F-010', step_name: 'Follow-up task', status: 'success', attempt_count: 1, payload_snapshot: { assigned_to: assignment.assigned_counselor?.email || null, task_priority: a.category === 'HOT' ? 'high' : (a.category === 'WARM' ? 'medium' : 'low') }, error_detail: null, started_at: new Date(now - 3000).toISOString(), finished_at: new Date(now - 2000).toISOString() },
  { run_id: runId, feature_id: 'F-011', step_name: 'Counselor notification', status: 'success', attempt_count: 1, payload_snapshot: { notified: assignment.assigned_counselor?.email || null, type: 'new_lead' }, error_detail: null, started_at: new Date(now - 2000).toISOString(), finished_at: new Date(now - 1000).toISOString() }
];

return [{ json: { rows } }];
